-- ============================================================================
-- B5 FOLLOW-ON W1, D4 PART C: the open-book label on the welltest capstone
-- brief.
--
-- WHY. A lesson or a panel's opening view prints the answers these capstones
-- grade (docs/graded-field-audit/README.md finding 3; FOLLOW-ON-PROGRAMME.md
-- section 3). Until W5 re-cases or strips them, the brief says so. The label is
-- the brief's first sentence; the rest of the prompt is unchanged. The same
-- note heads the tier's capstone lesson (NextGen zip).
--
-- beginner: every graded figure(s) printed; section 3 pick A (re-case)
-- intermediate: some graded figure(s) printed; section 3 pick B (strip)
-- advanced: some graded figure(s) printed; section 3 pick B (strip)
--
-- THE LABEL:
--   Open book, in part: some of the figures this capstone grades can be read in
--   this tier's lessons or on a panel as it opens, so for now those check that
--   you can find, read and report them correctly. A later update takes them out
--   of the lessons and panels.
--   Open book: the figures this capstone grades can be read in this tier's
--   lessons or on a panel as it opens, so for now it checks that you can find,
--   read and report each one correctly. A later update moves it to a case of its
--   own.
--
-- WHAT DOES NOT MOVE. `fields` (every key, label, unit, expected and
-- tolerance), title, dataset, status and the row. The guard requires `fields`
-- to equal its post-20261024a value exactly, before and after, so no answer
-- grades differently and no attempt guard is needed.
--
-- GUARDS. Each prompt must hold its post-20261024a text (md5, rewritten) or
-- its labelled text (left alone). Anything else raises and the file rolls
-- back. Runs after 20261024a_w1_*. Generated by
-- docs/graded-field-audit/w1_capstones.py. SAFE TO RE-RUN.
-- ============================================================================

do $$
declare
  v_n        integer;
  v_count    integer;
  v_written  integer := 0;
  v_ids      jsonb;
  v_extra    jsonb;
  v_idtxt    text;
  v_allow    jsonb := '{}'::jsonb;  -- D5 allowlist: 'course/tier' -> attempt ids signed off
  v_s0       text;
  v_s1       text;
  v_s2       text;
begin
  -- welltest / beginner
  select count(*) into v_n from public.academy_capstones where app_slug = 'welltest' and tier = 'beginner' and active;
  if v_n <> 1 then raise exception 'w1 open-book welltest refused: welltest/beginner has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = 'aa70d0ab9b83be3ce1b94f88a030eaa1' and fields = '[{"key": "horner_k_md", "tol": 0.05, "unit": "mD", "label": "Horner permeability", "expected": 82.49005478363101}, {"key": "horner_skin", "tol": 0.005, "unit": "-", "label": "Skin from the one-hour pressure", "expected": 6.075741352818642}, {"key": "horner_slope_psi_cycle", "tol": 0.005, "unit": "psi/cycle", "label": "Semilog slope", "expected": 22.175400474615625}, {"key": "horner_pstar_psia", "tol": 0.05, "unit": "psia", "label": "Extrapolated pressure p star", "expected": 4800.151625643111}, {"key": "skin_dp_psi", "tol": 0.05, "unit": "psi", "label": "Skin pressure drop", "expected": 116.99974214185609}, {"key": "ri_at_tp_ft", "tol": 0.5, "unit": "ft", "label": "Radius of investigation at 36 h", "expected": 1269.4036637344336}]'::jsonb then 'old'
              when md5(prompt) = '5f4d6e8c2f85acf547e09db4e46cb256' and fields = '[{"key": "horner_k_md", "tol": 0.05, "unit": "mD", "label": "Horner permeability", "expected": 82.49005478363101}, {"key": "horner_skin", "tol": 0.005, "unit": "-", "label": "Skin from the one-hour pressure", "expected": 6.075741352818642}, {"key": "horner_slope_psi_cycle", "tol": 0.005, "unit": "psi/cycle", "label": "Semilog slope", "expected": 22.175400474615625}, {"key": "horner_pstar_psia", "tol": 0.05, "unit": "psia", "label": "Extrapolated pressure p star", "expected": 4800.151625643111}, {"key": "skin_dp_psi", "tol": 0.05, "unit": "psi", "label": "Skin pressure drop", "expected": 116.99974214185609}, {"key": "ri_at_tp_ft", "tol": 0.5, "unit": "ft", "label": "Radius of investigation at 36 h", "expected": 1269.4036637344336}]'::jsonb then 'new'
              else 'other' end
    into v_s0 from public.academy_capstones where app_slug = 'welltest' and tier = 'beginner' and active;
  if v_s0 = 'other' then
    raise exception 'w1 open-book welltest refused: welltest/beginner matches neither its published form (prompt md5 aa70d0ab9b83be3ce1b94f88a030eaa1) nor its W1 form (prompt md5 5f4d6e8c2f85acf547e09db4e46cb256), with the fields this file was generated against';
  end if;

  -- welltest / intermediate
  select count(*) into v_n from public.academy_capstones where app_slug = 'welltest' and tier = 'intermediate' and active;
  if v_n <> 1 then raise exception 'w1 open-book welltest refused: welltest/intermediate has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '8db0da68e961136b890c7148d4cafa9d' and fields = '[{"key": "radial_plateau_psi", "tol": 0.005, "unit": "psi", "label": "Buildup radial derivative plateau", "expected": 9.590852793412228}, {"key": "fault_late_k_md", "tol": 0.05, "unit": "mD", "label": "Permeability from the late line", "expected": 45.25748634072017}, {"key": "fault_slope_ratio", "tol": 0.002, "unit": "-", "label": "Late slope over early slope", "expected": 1.795381509640958}, {"key": "fracture_sqrt_slope", "tol": 0.005, "unit": "psi/sqrt(h)", "label": "Linear-flow sqrt-time slope", "expected": 51.502350529498294}, {"key": "rect_drainage_area_ft2", "tol": 50, "unit": "ft2", "label": "Drainage area", "expected": 2800109.0707769613}, {"key": "dp_dip_ratio", "tol": 0.0005, "unit": "-", "label": "Derivative dip over late plateau", "expected": 0.27750746082216926}]'::jsonb then 'old'
              when md5(prompt) = 'e9a37660798a517b1ff9ef1952d9a13a' and fields = '[{"key": "radial_plateau_psi", "tol": 0.005, "unit": "psi", "label": "Buildup radial derivative plateau", "expected": 9.590852793412228}, {"key": "fault_late_k_md", "tol": 0.05, "unit": "mD", "label": "Permeability from the late line", "expected": 45.25748634072017}, {"key": "fault_slope_ratio", "tol": 0.002, "unit": "-", "label": "Late slope over early slope", "expected": 1.795381509640958}, {"key": "fracture_sqrt_slope", "tol": 0.005, "unit": "psi/sqrt(h)", "label": "Linear-flow sqrt-time slope", "expected": 51.502350529498294}, {"key": "rect_drainage_area_ft2", "tol": 50, "unit": "ft2", "label": "Drainage area", "expected": 2800109.0707769613}, {"key": "dp_dip_ratio", "tol": 0.0005, "unit": "-", "label": "Derivative dip over late plateau", "expected": 0.27750746082216926}]'::jsonb then 'new'
              else 'other' end
    into v_s1 from public.academy_capstones where app_slug = 'welltest' and tier = 'intermediate' and active;
  if v_s1 = 'other' then
    raise exception 'w1 open-book welltest refused: welltest/intermediate matches neither its published form (prompt md5 8db0da68e961136b890c7148d4cafa9d) nor its W1 form (prompt md5 e9a37660798a517b1ff9ef1952d9a13a), with the fields this file was generated against';
  end if;

  -- welltest / advanced
  select count(*) into v_n from public.academy_capstones where app_slug = 'welltest' and tier = 'advanced' and active;
  if v_n <> 1 then raise exception 'w1 open-book welltest refused: welltest/advanced has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '93fe4310d601bd945d53d61664e601b1' and fields = '[{"key": "fault_fit_distance_ft", "tol": 1.0, "unit": "ft", "label": "Fitted distance to the fault", "expected": 793.8937564207687}, {"key": "multirate_k_md", "tol": 0.05, "unit": "mD", "label": "Multi-rate semilog permeability", "expected": 83.40692632353809}, {"key": "equivalent_producing_time_h", "tol": 0.005, "unit": "hours", "label": "Equivalent producing time", "expected": 64.28571428571429}, {"key": "aof_disagreement_pct", "tol": 0.005, "unit": "percent", "label": "Back-pressure AOF over Houpeurt", "expected": 4.049138750335787}, {"key": "rta_oil_n_stb", "tol": 5, "unit": "stb", "label": "Oil in place, flowing MB", "expected": 1996864.3157109257}, {"key": "rta_gas_g_mscf", "tol": 50, "unit": "Mscf", "label": "Gas in place, dynamic MB", "expected": 19960373.229717568}]'::jsonb then 'old'
              when md5(prompt) = '8a397877a9426d217d9c1a4b4b99d617' and fields = '[{"key": "fault_fit_distance_ft", "tol": 1.0, "unit": "ft", "label": "Fitted distance to the fault", "expected": 793.8937564207687}, {"key": "multirate_k_md", "tol": 0.05, "unit": "mD", "label": "Multi-rate semilog permeability", "expected": 83.40692632353809}, {"key": "equivalent_producing_time_h", "tol": 0.005, "unit": "hours", "label": "Equivalent producing time", "expected": 64.28571428571429}, {"key": "aof_disagreement_pct", "tol": 0.005, "unit": "percent", "label": "Back-pressure AOF over Houpeurt", "expected": 4.049138750335787}, {"key": "rta_oil_n_stb", "tol": 5, "unit": "stb", "label": "Oil in place, flowing MB", "expected": 1996864.3157109257}, {"key": "rta_gas_g_mscf", "tol": 50, "unit": "Mscf", "label": "Gas in place, dynamic MB", "expected": 19960373.229717568}]'::jsonb then 'new'
              else 'other' end
    into v_s2 from public.academy_capstones where app_slug = 'welltest' and tier = 'advanced' and active;
  if v_s2 = 'other' then
    raise exception 'w1 open-book welltest refused: welltest/advanced matches neither its published form (prompt md5 93fe4310d601bd945d53d61664e601b1) nor its W1 form (prompt md5 8a397877a9426d217d9c1a4b4b99d617), with the fields this file was generated against';
  end if;

  -- nothing to write: every row is already in its W1 form
  if v_s0 = 'new' and v_s1 = 'new' and v_s2 = 'new' then
    raise notice 'w1 open-book welltest: 0 of 3 row(s) written, all already applied';
    return;
  end if;

  -- the round-off batch (20261023*) must be applied first: its rows are this file's base
  if exists (select 1 from public.academy_capstones where app_slug = 'cementing' and tier = 'advanced' and active and md5(prompt) <> '7e7412057740dcb01936e298c2026745')
     or exists (select 1 from public.academy_capstones where app_slug = 'casingtubing' and tier = 'advanced' and active and md5(prompt) <> 'f7e6749b9be66d4dbc7e692745d656d7')
     or exists (select 1 from public.academy_capstones where app_slug = 'gaswell' and tier = 'advanced' and active and md5(prompt) <> '07f6076362de4a93714236cc10af4012')
     or exists (select 1 from public.academy_capstones where app_slug = 'wellcontrol' and tier = 'beginner' and active and md5(dataset) <> '228b1d1a73f0474291f6142741bab7b2')
     or exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                 where c.app_slug = 'fiscal' and c.tier = 'intermediate' and c.active and f->>'key' = 'psc_npv_musd'
                   and (f->>'tol')::float8 <> 0.05) then
    raise exception 'w1 open-book welltest refused: the round-off batch (20261023*) is not applied on this database; apply it first (/root/roundoff-apply/apply.sh apply --prod)';
  end if;

  if v_s0 = 'old' then
    update public.academy_capstones
       set prompt = 'Open book: the figures this capstone grades can be read in this tier''s lessons or on a panel as it opens, so for now it checks that you can find, read and report each one correctly. A later update moves it to a case of its own. Analyse one pressure buildup and report six quantities from ONE fit. The well produced at 450 stb/d for 36 hours and was shut in at a flowing pressure of 4530.771773811249 psia; the reservoir has porosity 0.18, viscosity 0.9 cp, total compressibility 1.2e-5 per psi, wellbore radius 0.354 ft, net pay 45 ft, formation volume factor 1.25 rb/stb and an initial pressure of 4800 psia. Fit a Horner semilog line by least squares to the THIRTEEN points whose shut-in time is 5 hours or more, and report: the permeability that line implies; the skin, taking the line''s value at one hour of shut-in as the reference; the magnitude of the semilog slope in psi per cycle; the pressure the line extrapolates to at a Horner ratio of one; the skin pressure drop, and the radius of investigation at the 36 hour producing time. The last two must use the permeability and skin YOU reported, not the values the fixture was built from.',
           fields = '[{"key": "horner_k_md", "tol": 0.05, "unit": "mD", "label": "Horner permeability", "expected": 82.49005478363101}, {"key": "horner_skin", "tol": 0.005, "unit": "-", "label": "Skin from the one-hour pressure", "expected": 6.075741352818642}, {"key": "horner_slope_psi_cycle", "tol": 0.005, "unit": "psi/cycle", "label": "Semilog slope", "expected": 22.175400474615625}, {"key": "horner_pstar_psia", "tol": 0.05, "unit": "psia", "label": "Extrapolated pressure p star", "expected": 4800.151625643111}, {"key": "skin_dp_psi", "tol": 0.05, "unit": "psi", "label": "Skin pressure drop", "expected": 116.99974214185609}, {"key": "ri_at_tp_ft", "tol": 0.5, "unit": "ft", "label": "Radius of investigation at 36 h", "expected": 1269.4036637344336}]'::jsonb
     where app_slug = 'welltest' and tier = 'beginner' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 open-book welltest refused: welltest/beginner updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '5f4d6e8c2f85acf547e09db4e46cb256' and fields = '[{"key": "horner_k_md", "tol": 0.05, "unit": "mD", "label": "Horner permeability", "expected": 82.49005478363101}, {"key": "horner_skin", "tol": 0.005, "unit": "-", "label": "Skin from the one-hour pressure", "expected": 6.075741352818642}, {"key": "horner_slope_psi_cycle", "tol": 0.005, "unit": "psi/cycle", "label": "Semilog slope", "expected": 22.175400474615625}, {"key": "horner_pstar_psia", "tol": 0.05, "unit": "psia", "label": "Extrapolated pressure p star", "expected": 4800.151625643111}, {"key": "skin_dp_psi", "tol": 0.05, "unit": "psi", "label": "Skin pressure drop", "expected": 116.99974214185609}, {"key": "ri_at_tp_ft", "tol": 0.5, "unit": "ft", "label": "Radius of investigation at 36 h", "expected": 1269.4036637344336}]'::jsonb) from public.academy_capstones where app_slug = 'welltest' and tier = 'beginner' and active) is not true then
    raise exception 'w1 open-book welltest refused: welltest/beginner does not read back as its W1 form';
  end if;

  if v_s1 = 'old' then
    update public.academy_capstones
       set prompt = 'Open book, in part: some of the figures this capstone grades can be read in this tier''s lessons or on a panel as it opens, so for now those check that you can find, read and report them correctly. A later update takes them out of the lessons and panels. Diagnose four pressure transients and report one number from each, at the settings stated. Use a Bourdet smoothing window L of 0.1 throughout. (1) On the BUILDUP, differentiated against Agarwal equivalent time with the fixture''s own pressure change, report the arithmetic mean of the derivative over the twelve points whose equivalent time is 5 hours or more. (2) On the SEALING FAULT test, fit MDH semilog lines to the flowing pressures over 1 to 20 hours and over 200 to 1000 hours, and report the permeability the LATE line implies. (3) Report the ratio of that late line''s slope to the early line''s. (4) On the FRACTURED well, fit pressure change against the square root of time in hours over 0.1 to 10 hours and report the slope. (5) On the CLOSED RECTANGLE, fit flowing pressure against time over 500 hours and later, convert the Cartesian slope to a pore volume and divide by porosity times net pay, and report the drainage area in SQUARE FEET. (6) On the DUAL POROSITY test, report the minimum derivative between 0.05 and 50 hours divided by the mean derivative from 300 hours on.',
           fields = '[{"key": "radial_plateau_psi", "tol": 0.005, "unit": "psi", "label": "Buildup radial derivative plateau", "expected": 9.590852793412228}, {"key": "fault_late_k_md", "tol": 0.05, "unit": "mD", "label": "Permeability from the late line", "expected": 45.25748634072017}, {"key": "fault_slope_ratio", "tol": 0.002, "unit": "-", "label": "Late slope over early slope", "expected": 1.795381509640958}, {"key": "fracture_sqrt_slope", "tol": 0.005, "unit": "psi/sqrt(h)", "label": "Linear-flow sqrt-time slope", "expected": 51.502350529498294}, {"key": "rect_drainage_area_ft2", "tol": 50, "unit": "ft2", "label": "Drainage area", "expected": 2800109.0707769613}, {"key": "dp_dip_ratio", "tol": 0.0005, "unit": "-", "label": "Derivative dip over late plateau", "expected": 0.27750746082216926}]'::jsonb
     where app_slug = 'welltest' and tier = 'intermediate' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 open-book welltest refused: welltest/intermediate updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = 'e9a37660798a517b1ff9ef1952d9a13a' and fields = '[{"key": "radial_plateau_psi", "tol": 0.005, "unit": "psi", "label": "Buildup radial derivative plateau", "expected": 9.590852793412228}, {"key": "fault_late_k_md", "tol": 0.05, "unit": "mD", "label": "Permeability from the late line", "expected": 45.25748634072017}, {"key": "fault_slope_ratio", "tol": 0.002, "unit": "-", "label": "Late slope over early slope", "expected": 1.795381509640958}, {"key": "fracture_sqrt_slope", "tol": 0.005, "unit": "psi/sqrt(h)", "label": "Linear-flow sqrt-time slope", "expected": 51.502350529498294}, {"key": "rect_drainage_area_ft2", "tol": 50, "unit": "ft2", "label": "Drainage area", "expected": 2800109.0707769613}, {"key": "dp_dip_ratio", "tol": 0.0005, "unit": "-", "label": "Derivative dip over late plateau", "expected": 0.27750746082216926}]'::jsonb) from public.academy_capstones where app_slug = 'welltest' and tier = 'intermediate' and active) is not true then
    raise exception 'w1 open-book welltest refused: welltest/intermediate does not read back as its W1 form';
  end if;

  if v_s2 = 'old' then
    update public.academy_capstones
       set prompt = 'Open book, in part: some of the figures this capstone grades can be read in this tier''s lessons or on a panel as it opens, so for now those check that you can find, read and report them correctly. A later update takes them out of the lessons and panels. Six analyses on five datasets, at the engine''s default settings throughout: Bourdet smoothing L of 0.1, derivative weight 1, and the model catalog''s own starting values and bounds. (1) Fit the homogeneous-plus-sealing-fault model to the SEALING FAULT drawdown, using that fixture''s own pressure change, and report the fitted distance to the boundary in feet. (2) Build the three-rate drawdown by superposing the planted homogeneous response at 450 stb/d for 24 hours, 250 for 36 and 700 thereafter, and report the permeability the multi-rate semilog analysis returns from the late points of the three periods. (3) With the well shut in at 96 hours, report the equivalent producing time in hours. (4) For the flow-after-flow test at an average reservoir pressure of 1952 psia, with 2624.6, 4154.7 and 5425.1 Mscf/d flowing at 1700, 1500 and 1300 psia, fit both the Rawlins-Schellhardt and the Houpeurt forms in pressure-squared space, evaluate both absolute open flows at a base pressure of 14.7 psia, and report the percentage by which the back-pressure value exceeds the Houpeurt one, RELATIVE TO the Houpeurt one. (5) From the 80-day oil decline, report the oil in place the flowing material balance gives at a total compressibility of 1.2e-5 per psi. (6) From the 300-day gas decline at 0.65 gravity and 180 F, report the gas in place the dynamic material balance converges on, using pseudo-pressure and material-balance pseudo-time on a 200-point PVT table to 10000 psia. Fields 5 and 6 are not the planted values.',
           fields = '[{"key": "fault_fit_distance_ft", "tol": 1.0, "unit": "ft", "label": "Fitted distance to the fault", "expected": 793.8937564207687}, {"key": "multirate_k_md", "tol": 0.05, "unit": "mD", "label": "Multi-rate semilog permeability", "expected": 83.40692632353809}, {"key": "equivalent_producing_time_h", "tol": 0.005, "unit": "hours", "label": "Equivalent producing time", "expected": 64.28571428571429}, {"key": "aof_disagreement_pct", "tol": 0.005, "unit": "percent", "label": "Back-pressure AOF over Houpeurt", "expected": 4.049138750335787}, {"key": "rta_oil_n_stb", "tol": 5, "unit": "stb", "label": "Oil in place, flowing MB", "expected": 1996864.3157109257}, {"key": "rta_gas_g_mscf", "tol": 50, "unit": "Mscf", "label": "Gas in place, dynamic MB", "expected": 19960373.229717568}]'::jsonb
     where app_slug = 'welltest' and tier = 'advanced' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 open-book welltest refused: welltest/advanced updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '8a397877a9426d217d9c1a4b4b99d617' and fields = '[{"key": "fault_fit_distance_ft", "tol": 1.0, "unit": "ft", "label": "Fitted distance to the fault", "expected": 793.8937564207687}, {"key": "multirate_k_md", "tol": 0.05, "unit": "mD", "label": "Multi-rate semilog permeability", "expected": 83.40692632353809}, {"key": "equivalent_producing_time_h", "tol": 0.005, "unit": "hours", "label": "Equivalent producing time", "expected": 64.28571428571429}, {"key": "aof_disagreement_pct", "tol": 0.005, "unit": "percent", "label": "Back-pressure AOF over Houpeurt", "expected": 4.049138750335787}, {"key": "rta_oil_n_stb", "tol": 5, "unit": "stb", "label": "Oil in place, flowing MB", "expected": 1996864.3157109257}, {"key": "rta_gas_g_mscf", "tol": 50, "unit": "Mscf", "label": "Gas in place, dynamic MB", "expected": 19960373.229717568}]'::jsonb) from public.academy_capstones where app_slug = 'welltest' and tier = 'advanced' and active) is not true then
    raise exception 'w1 open-book welltest refused: welltest/advanced does not read back as its W1 form';
  end if;

  raise notice 'w1 open-book welltest: % of 3 row(s) written, % already applied', v_written, 3 - v_written;
end $$;
